/bin/bash -lc "curl -sS -o /tmp/margin-home.html -w '%{http_code} %{size_download}\\n' http://localhost:3000/ && python - <<'PY'
from html.parser import HTMLParser
class Forms(HTMLParser):
    def __init__(self):
        super().__init__(); self.in_form=False; self.forms=[]
    def handle_starttag(self, tag, attrs):
        d=dict(attrs)
        if tag=='form': self.forms.append({'action':d.get('action'),'method':d.get('method'),'inputs':[]})
        if tag=='input' and self.forms: self.forms[-1]['inputs'].append((d.get('name'),d.get('value')))
p=Forms(); p.feed(open('/tmp/margin-home.html').read()); print(p.forms)
PY"

